    if (unitRows.length > 0) {
      unitRows.forEach(u => rentRows.push(u.innerText?.replace(/\n+/g, ' ')));
    } else {
      const pText = p.innerText.split('\n').map(x => x.trim()).filter(Boolean);
      for (let j = 0; j < pText.length; j++) {
        if (pText[j].match(/\b(Studio|\d+\s*Beds?)\b/i) && pText[j+1] && pText[j+1].includes('$')) {
          rentRows.push(`${pText[j]}: ${pText[j+1]}`);
        }
      }
    }

    const amenities = p.querySelector('.property-amenities')?.innerText?.trim();
    const phone = p.querySelector('.phone-link, a[href^="tel:"]')?.innerText?.trim();
    const link = p.querySelector('a.property-link')?.href;

    return {
      index: i + 1,
      title,
      address,
      rentDetails: rentRows.length > 0 ? rentRows.join(' | ') : 'Contact for pricing',
      amenities,
      phone,
      link
    };
  });
});

