const tabId = 343605414;
const allApartments = await browserjs(tabId, () => {
  const placards = Array.from(document.querySelectorAll('article.placard'));
  return placards.map((p, i) => {
    const title = p.querySelector('.property-title')?.innerText?.trim() 
      || p.querySelector('a.property-link')?.getAttribute('title')
      || p.querySelector('.property-information a')?.innerText?.trim()
      || p.querySelector('a.property-link')?.innerText?.split('\n')[0]?.trim();

    const address = p.querySelector('.property-address')?.innerText?.trim();

    // Extract pricing and beds cleanly
    // Often there are elements with beds and price
    const rentRows = [];
    const unitRows = p.querySelectorAll('.unit-container, .pricingGridItem, .price-bed-checkbox-wrapper');
    if (unitRows.length > 0) {
      unitRows.forEach(u => rentRows.push(u.innerText?.replace(/\n+/g, ' ')));
    } else {
      const pText = p.innerText.split('\n').map(x => x.trim()).filter(Boolean);
      for (let j = 0; j < pText.length; j++) {
        if (pText[j].match(/\b(Studio|\d+\s*Beds?)\b/i) && pText[j+1] && pText[j+1].includes('$')) {
          rentRows.push(`${pText[j]}: ${pText[j+1]}`);
        }
      }
    }

    const amenities = p.querySelector('.property-amenities')?.innerText?.trim();
    const phone = p.querySelector('.phone-link, a[href^="tel:"]')?.innerText?.trim();
    const link = p.querySelector('a.property-link')?.href;

    return {
      index: i + 1,
      title,
      address,
      rentDetails: rentRows.length > 0 ? rentRows.join(' | ') : 'Contact for pricing',
      amenities,
      phone,
      link
    };
  });
});

console.log(JSON.stringify(allApartments, null, 2));

